def even_odd_count(num):
    """Given an integer, return a tuple (even_count, odd_count) representing the number
    of even and odd digits in its decimal representation.

    Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    # Work with absolute value to ignore sign
    n = abs(num)

    # Special case for 0, which has one even digit
    if n == 0:
        return (1, 0)

    even = odd = 0
    while n > 0:
        digit = n % 10
        if digit % 2 == 0:
            even += 1
        else:
            odd += 1
        n //= 10
    return (even, odd)
