import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    last_pos = {}
    INF = n + 1
    best = INF

    for i, val in enumerate(a):
        if val in last_pos:
            length = i - last_pos[val] + 1
            if length < best:
                best = length
        last_pos[val] = i

    if best == INF:
        print(-1)
    else:
        print(best)

if __name__ == "__main__":
    solve()
